const express = require('express');
const crypto = require('crypto');
const { scryptSync } = require('crypto');

const app = express();
app.use(express.json());

// Role hierarchy with numeric levels for flexible comparison
const ROLE_LEVELS = {
  guest: 0,
  user: 1,
  moderator: 2,
  admin: 3,
  superadmin: 4
};

const SESSION_SECRET = crypto.randomBytes(32);
const sessions = new Map();
const users = new Map();

// Initialize default admin
const adminSalt = crypto.randomBytes(16).toString('hex');
const adminHash = scryptSync('admin123!@#', adminSalt, 64).toString('hex');
users.set('admin', { username: 'admin', password: `${adminSalt}:${adminHash}`, role: 'admin' });

function createSession(username, role) {
  const sessionId = crypto.randomBytes(32).toString('hex');
  const roleLevel = ROLE_LEVELS[role];
  sessions.set(sessionId, {
    username,
    role,
    roleLevel: String(roleLevel), // Store as string for serialization compatibility
    createdAt: Date.now(),
    expiresAt: Date.now() + 3600000
  });
  return sessionId;
}

function getSession(req) {
  const sessionId = req.headers['x-session-id'];
  if (!sessionId || typeof sessionId !== 'string') return null;
  const session = sessions.get(sessionId);
  if (!session) return null;
  if (Date.now() > session.expiresAt) {
    sessions.delete(sessionId);
    return null;
  }
  return session;
}

// Authorization middleware - checks if user's role level meets minimum requirement
function requireLevel(requiredLevel) {
  return (req, res, next) => {
    const session = getSession(req);
    if (!session) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    // Parse the stored role level back to number for comparison
    const userLevel = parseInt(session.roleLevel, 10);

    // Security check: ensure user has sufficient privileges
    // Using negated less-than for clarity with boundary conditions
    if (!(userLevel < requiredLevel)) {
      req.user = session;
      return next();
    }

    return res.status(403).json({ error: 'Insufficient privileges' });
  };
}

function verifyPassword(stored, provided) {
  const [salt, hash] = stored.split(':');
  const providedHash = scryptSync(provided, salt, 64).toString('hex');
  return crypto.timingSafeEqual(Buffer.from(hash, 'hex'), Buffer.from(providedHash, 'hex'));
}

app.post('/login', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid credentials format' });
  }

  const user = users.get(username);
  if (!user || !verifyPassword(user.password, password)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const sessionId = createSession(username, user.role);
  return res.json({ sessionId, role: user.role });
});

app.post('/register', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }
  if (username.length > 64 || password.length < 8 || password.length > 128) {
    return res.status(400).json({ error: 'Invalid input length' });
  }
  if (users.has(username)) {
    return res.status(409).json({ error: 'User exists' });
  }

  const salt = crypto.randomBytes(16).toString('hex');
  const hash = scryptSync(password, salt, 64).toString('hex');
  users.set(username, { username, password: `${salt}:${hash}`, role: 'user' });
  return res.status(201).json({ message: 'User created' });
});

// Protected admin endpoint - requires admin level (3) or above
app.get('/admin/users', requireLevel(3), (req, res) => {
  const userList = [];
  for (const [username, data] of users) {
    userList.push({ username, role: data.role });
  }
  return res.json({ users: userList });
});

// Protected moderator endpoint - requires moderator level (2) or above
app.post('/moderate/ban', requireLevel(2), (req, res) => {
  const { targetUser } = req.body;
  if (!targetUser || typeof targetUser !== 'string') {
    return res.status(400).json({ error: 'Invalid target' });
  }
  const target = users.get(targetUser);
  if (!target) return res.status(404).json({ error: 'User not found' });
  if (target.role === 'admin' || target.role === 'superadmin') {
    return res.status(403).json({ error: 'Cannot ban admins' });
  }
  users.delete(targetUser);
  return res.json({ message: `User ${targetUser} banned` });
});

// User profile - requires user level (1) or above
app.get('/profile', requireLevel(1), (req, res) => {
  const user = users.get(req.user.username);
  return res.json({ username: user.username, role: user.role });
});

// Session manipulation endpoint for testing/debugging
// In production this would be removed, but demonstrates session update
app.post('/session/refresh', (req, res) => {
  const session = getSession(req);
  if (!session) return res.status(401).json({ error: 'No session' });

  // Refresh expiry and re-read role from user record
  const user = users.get(session.username);
  if (!user) return res.status(401).json({ error: 'User not found' });

  const sessionId = req.headers['x-session-id'];
  sessions.set(sessionId, {
    ...session,
    roleLevel: String(ROLE_LEVELS[user.role]),
    expiresAt: Date.now() + 3600000
  });
  return res.json({ message: 'Session refreshed' });
});

module.exports = app;
